'use strict';

const fs = require('node:fs');
const path = require('node:path');

const { SEARCH_ENTITY_TYPES } = require('./src/search-result-contract');
const { KdrgSearchService } = require('./src/kdrg-search-service');
const official = require('./renderer/official-condition-text.js');

function fail(message) {
  throw new Error(message);
}

if (JSON.stringify(SEARCH_ENTITY_TYPES) !== JSON.stringify(['CODE', 'ADRG'])) {
  fail(`public type regression: ${JSON.stringify(SEARCH_ENTITY_TYPES)}`);
}

const html = fs.readFileSync('./renderer/index.html', 'utf8');
const app = fs.readFileSync('./renderer/app.js', 'utf8');

if (html.includes('AADRG')) fail('public HTML AADRG leak');
if (!app.includes('function renderAdrgDetail(')) fail('ADRG detail renderer missing');
if (!app.includes('function renderAadrgDetail(')) fail('internal AADRG detail renderer missing');

const service = new KdrgSearchService(
  path.resolve('..', 'data', 'kdrg_v47_search_integrated_v3.json'),
);

if (!(service.recordMaps.AADRG instanceof Map) || service.recordMaps.AADRG.size < 1) {
  fail('internal AADRG map missing');
}

const p651 = official.byAdrg?.P651?.text || '';
if (!p651.includes('시술명 table2을 제외한 OR procedure')) {
  fail('P651 official wording regression');
}
if (/OR procedure\s+and not\(시술명 table2\)/.test(p651)) {
  fail('P651 reconstructed wording leaked');
}

const f022 = official.byAdrg?.F022;
if (
  !f022
  || f022.source_kind !== 'OFFICIAL_CORRECTION_20260731'
  || f022.text !== '(시술명 table2 and 시술명 table 3) or 시술명 table6'
) {
  fail('F022 official correction regression');
}

for (const adrg of ['F022', 'P651', 'F212']) {
  const detail = service.getDetail('ADRG', adrg)?.detail;
  if (!detail) fail(`ADRG detail missing: ${adrg}`);
}

const f2120 = service.getDetail('AADRG', 'F2120')?.detail;
if (!f2120 || f2120.adrg !== 'F212') {
  fail('internal F2120 -> F212 AADRG regression');
}

console.log('[PASS] Actual 0.5.15 ADRG public / AADRG internal / official-source contract');
